<script setup lang="ts">
import { computed, ref } from 'vue';
import type { ReminiscenceSettings } from '../../../../packages/contracts/src/plugins/reminiscence';
import { ReminiscenceOverviewSchema } from '../../../../packages/contracts/src/plugins/reminiscence';
const settings=defineModel<ReminiscenceSettings>({required:true});
const props=defineProps<{overview?:ReturnType<typeof ReminiscenceOverviewSchema.parse>}>();
const emit=defineEmits<{action:[value:{operation:'daily'|'consolidate'|'reindex'|'delete_day';scopeKey:string;date:string}];reload:[]}>();
const scopeKey=ref('');const date=ref(new Date().toISOString().slice(0,10));const kind=ref('all');
const records=computed(()=>props.overview?.records.filter(r=>(!scopeKey.value||r.scope.key===scopeKey.value)&&(kind.value==='all'||r.kind===kind.value))??[]);
const numericFields: {key:'topResults'|'maxContextChars'|'maxSummaryChars'|'retentionDays'|'maxRecordsPerScope'|'minSimilarity'|'importanceWeight'|'recencyWeight'|'emotionWeight';label:string;min:number;max:number;step:number}[]=[{key:'topResults',label:'返回结果数',min:1,max:20,step:1},{key:'maxContextChars',label:'上下文字符上限',min:500,max:16000,step:1},{key:'maxSummaryChars',label:'每次摘要输入字符上限',min:2000,max:100000,step:1},{key:'retentionDays',label:'原始记录保留天数',min:1,max:3650,step:1},{key:'maxRecordsPerScope',label:'每范围记录上限',min:50,max:20000,step:1},{key:'minSimilarity',label:'最低相关度',min:0,max:1,step:0.01},{key:'importanceWeight',label:'重要性权重',min:0,max:5,step:0.05},{key:'recencyWeight',label:'近期权重',min:0,max:5,step:0.05},{key:'emotionWeight',label:'情感强度权重',min:0,max:5,step:0.05}];
function targets(event:Event){if(event.target instanceof HTMLTextAreaElement)settings.value.targetSessions=event.target.value.split('\n').map(v=>v.trim()).filter(Boolean);}
function action(operation:'daily'|'consolidate'|'reindex'|'delete_day'){if(scopeKey.value)emit('action',{operation,scopeKey:scopeKey.value,date:date.value});}
</script>
<template><section class="ts-fields"><p class="muted">本页参数在下方保存插件配置后生效。回忆整理和删除使用已保存的设置，并独立执行。</p><h3>本地回忆</h3><p class="muted">按平台、会话类型、会话、发送者和 Agent 隔离事件、心得、主题与实体节点。整理使用当前 Agent 的摘要模型。</p><div class="ts-form-grid"><label class="ts-check"><input v-model="settings.enabled" type="checkbox">启用</label><label class="ts-check"><input v-model="settings.realtimeRecording" type="checkbox">记录新对话</label><label class="ts-check"><input v-model="settings.autoRecall" type="checkbox">自动检索注入上下文</label><label class="ts-check"><input v-model="settings.autoSummary" type="checkbox">每日分界后自动整理</label><label>时区<input v-model="settings.timezone"></label><label>每日分界时<input v-model.number="settings.dayBoundaryHour" type="number" min="0" max="23"></label><label>每日分界分<input v-model.number="settings.dayBoundaryMinute" type="number" min="0" max="59"></label><label v-for="field in numericFields" :key="field.key">{{field.label}}<input v-model.number="settings[field.key]" type="number" :min="field.min" :max="field.max" :step="field.step"></label></div><label>目标会话 ID（每行一个，留空允许所有已授权会话）<textarea :value="settings.targetSessions.join('\n')" rows="3" @input="targets"></textarea></label><section class="card ts-fields"><h4>检索方式</h4><label>模式<select v-model="settings.embedding.mode"><option value="lexical">本地词项匹配（无需模型）</option><option value="local_endpoint">本机 Embedding 服务</option></select></label><template v-if="settings.embedding.mode==='local_endpoint'"><label>本机端点<input v-model="settings.embedding.endpoint"></label><label>模型名称<input v-model="settings.embedding.model"></label><label>超时毫秒<input v-model.number="settings.embedding.timeoutMs" type="number" min="1000" max="60000"></label><p class="muted">需预先启动兼容 /v1/embeddings 的本机服务；容器中 localhost 指容器自身。更换模型后重建向量，待重建记录暂用词项匹配。</p></template><p v-else class="muted">当前使用本地词项匹配，不是语义向量检索。</p></section><details class="card"><summary>整理提示词</summary><label>事件和心得<textarea v-model="settings.summaryPrompt" rows="5"></textarea></label><label>主题归纳<textarea v-model="settings.topicPrompt" rows="4"></textarea></label></details><p class="muted">记录需要 memory.write 和 reminiscence_record 工具；读取需要 memory.read 和相应检索工具。自动整理默认关闭；不会自动重置会话或推送消息。当前只整理启用后记录的新消息。</p><section v-if="overview" class="card ts-fields"><div class="section-title"><h4>回忆管理</h4><button type="button" @click="emit('reload')">刷新</button></div><label>范围<select v-model="scopeKey"><option value="">全部范围（操作时必须选择）</option><option v-for="scope in overview.scopes" :key="scope.key" :value="scope.key">{{scope.platform}} / {{scope.sessionType}} / {{scope.sessionId}} / {{scope.senderId}} / {{scope.agentId}}</option></select></label><div class="toolbar"><label>日期<input v-model="date" type="date"></label><button type="button" :disabled="!scopeKey" @click="action('daily')">整理该日</button><button type="button" :disabled="!scopeKey" @click="action('consolidate')">归纳主题</button><button type="button" :disabled="!scopeKey||settings.embedding.mode!=='local_endpoint'" @click="action('reindex')">重建向量</button><button type="button" :disabled="!scopeKey" @click="action('delete_day')">删除该日回忆与记录</button></div><label>内容类型<select v-model="kind"><option value="all">全部</option><option value="event">事件</option><option value="reflection">心得</option><option value="topic">主题</option><option value="node">节点</option></select></label><article v-for="record in records.slice(0,100)" :key="record.id" class="card"><strong>{{record.title}}</strong><small>{{record.date}} · {{record.kind}}</small><p style="white-space:pre-wrap">{{record.text}}</p><small>来源：{{record.sources.join('、')}}</small></article><p v-if="!records.length" class="muted">当前范围没有已整理回忆。</p><details><summary>作业记录（{{overview.jobs.length}}）</summary><p v-for="job in overview.jobs.filter(j=>!scopeKey||j.scope.key===scopeKey).slice(-50).reverse()" :key="job.id">{{job.date}} · {{job.kind}} · {{job.state}} · {{job.inputCount}} → {{job.outputCount}} {{job.error}}</p></details></section></section></template>
